package com.infosys.carbonfootprint.controller;
import com.infosys.carbonfootprint.dto.RecommendationDto; import com.infosys.carbonfootprint.response.ApiResponse; import com.infosys.carbonfootprint.security.UserDetailsImpl; import com.infosys.carbonfootprint.service.RecommendationService; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import java.util.*;
@RestController @RequestMapping("/api/v1/user/recommendations") @PreAuthorize("hasRole('USER')") public class RecommendationController { private final RecommendationService service; public RecommendationController(RecommendationService service){this.service=service;} @GetMapping("/top-emissions") public ApiResponse<List<RecommendationDto>> top(@AuthenticationPrincipal UserDetailsImpl user){return ApiResponse.success("Top emissions fetched",service.topEmissions(user.getId()));} }